    $f->now=$f->now->modify('+1 hour');$faultId=$f->uuid();$owner->requestPasswordReset('other.person@shlz.ru',$faultId,'192.0.2.8');$faultToken=$f->token($owner,$faultId,$mail);$trigger=$w->p.'reset_event_fault';$w->db->query("CREATE TRIGGER $trigger BEFORE INSERT ON {$w->p}fm2_password_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture reset fault'");$before=$f->snapshot();$failed=false;try{$owner->resetPassword($faultToken,PasswordAccessFixture::PASSWORD,PasswordAccessFixture::PASSWORD);}catch(Throwable){$failed=true;}assertSameValue(true,$failed,'reset audit failure');assertSameValue($before,$f->snapshot(),'hash/grants/session version rollback');$w->db->query("DROP TRIGGER $trigger");
